import React, { useState, useEffect } from "react"; // Importer useEffect

const Dashboard = () => {
  const [activeSection, setActiveSection] = useState("accueil");
  const [selectedEntreprise, setSelectedEntreprise] = useState("");
  const [showModal, setShowModal] = useState(false);
  const [showAddEntrepriseModal, setShowAddEntrepriseModal] = useState(false);
  const [selectedDocument, setSelectedDocument] = useState(null);
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [addEntrepriseData, setAddEntrepriseData] = useState({
    nom: "",
    siret: "",
    telephone: "",
    email: "",
    nomRepresentant: "",
    prenomRepresentant: "",
    domainesActivite: [],
    secteurActivite: "",
  });
  const [profileData, setProfileData] = useState({
    nom: "Logo service",
    siret: "12345678901234",
    adresse: "Ouagadougou 01 BP 824",
    email: "contact@techbat.fr",
    telephone: "0123456789",
    nomRepresentant: "Rayaissse ",
    prenomRepresentant: "Jude",
    secteurActivite: "Develloppement",
  });
  const [filters, setFilters] = useState({
    domaine: "",
    dateDebut: "",
    dateFin: "",
  });

  // Nouvel état pour les publications récupérées de l'API
  const [publications, setPublications] = useState([]);
  const [loadingPublications, setLoadingPublications] = useState(true);
  const [errorPublications, setErrorPublications] = useState(null);

  const entreprises = [
    { id: 1, nom: "SARL TechBat" },
    { id: 2, nom: "Construction Plus" },
    { id: 3, nom: "Eco Habitat" },
  ];

  // Le tableau hardcodé `publications` n'est plus nécessaire ici
  // const publications = [
  //   {
  //     id: 1,
  //     date: "15/06/2025",
  //     titre: "Construction école primaire - Ville de Ouaga",
  //     echeance: "30/07/2025",
  //     domaine: "Construction neuve",
  //   },
  //   {
  //     id: 2,
  //     date: "14/06/2025",
  //     titre: "Rénovation énergétique bâtiments publics",
  //     echeance: "25/07/2025",
  //     domaine: "Rénovation",
  //   },
  //   {
  //     id: 3,
  //     date: "13/06/2025",
  //     titre: "Travaux voirie quartier centre-ville",
  //     echeance: "20/08/2025",
  //     domaine: "Génie civil",
  //   },
  // ];

  const alertes = [
    {
      id: 1,
      titre: "Nouvel appel d'offres correspondant à vos critères",
      date: "16/06/2025",
    },
    {
      id: 2,
      titre: "Résultat publié pour consultation précédente",
      date: "15/06/2025",
    },
  ];

  const domainesActivite = [
    "Construction neuve",
    "Rénovation",
    "Génie civil",
    "Électricité",
    "Plomberie",
    "Isolation thermique",
  ];

  const secteursActivite = [
    "Bâtiment et Travaux Publics (BTP)",
    "Commerce général",
    "Transport et logistique",
    "Énergie et électricité",
    "Éducation et formation",
    "Agriculture et élevage",
  ];

  // Hook useEffect pour récupérer les publications
  useEffect(() => {
    const fetchPublications = async () => {
      try {
        const response = await fetch(
          "http://127.0.0.1:8000/api/backend/api/publications/"
        );
        if (!response.ok) {
          throw new Error(`HTTP error! status: ${response.status}`);
        }
        const data = await response.json();
        // Assurez-vous que les données reçues correspondent au format attendu
        // Si votre API renvoie un tableau d'objets avec `id`, `date`, `titre`, `echeance`, `domaine`, c'est parfait.
        // Sinon, vous devrez peut-être mapper les données ici pour les adapter.
        setPublications(data);
      } catch (error) {
        setErrorPublications(error);
        console.error(
          "Erreur lors de la récupération des publications:",
          error
        );
      } finally {
        setLoadingPublications(false);
      }
    };

    fetchPublications();
  }, []); // Le tableau vide [] signifie que cet effet ne s'exécutera qu'une seule fois après le rendu initial

  const handleAddEntrepriseDomaine = (domaine) => {
    const newDomaines = addEntrepriseData.domainesActivite.includes(domaine)
      ? addEntrepriseData.domainesActivite.filter((d) => d !== domaine)
      : [...addEntrepriseData.domainesActivite, domaine];

    setAddEntrepriseData({
      ...addEntrepriseData,
      domainesActivite: newDomaines,
    });
  };

  const handleSubmitAddEntreprise = (e) => {
    e.preventDefault();
    // Ici vous ajouteriez la logique pour sauvegarder l'entreprise
    console.log("Nouvelle entreprise:", addEntrepriseData);
    setShowAddEntrepriseModal(false);
    // Réinitialiser le formulaire
    setAddEntrepriseData({
      nom: "",
      siret: "",
      telephone: "",
      email: "",
      nomRepresentant: "",
      prenomRepresentant: "",
      domainesActivite: [],
      secteurActivite: "",
    });
  };

  const filteredPublications = publications.filter((pub) => {
    if (filters.domaine && pub.domaine !== filters.domaine) return false;
    if (filters.dateDebut && pub.date < filters.dateDebut) return false;
    if (filters.dateFin && pub.date > filters.dateFin) return false;
    return true;
  });

  const renderSidebar = () => (
    <>
      {/* Mobile overlay */}
      <div
        className={`sidebar-overlay ${sidebarOpen ? "show" : ""}`}
        onClick={() => setSidebarOpen(false)}
      ></div>

      <div className={`sidebar ${sidebarOpen ? "show" : ""}`}>
        <div className="sidebar-header">
          <h4>VeilleMarches Pro</h4>
          <button
            className="btn-close-sidebar d-md-none"
            onClick={() => setSidebarOpen(false)}
          >
            <svg width="24" height="24" fill="currentColor" viewBox="0 0 16 16">
              <path d="M4.646 4.646a.5.5 0 0 1 .708 0L8 7.293l2.646-2.647a.5.5 0 0 1 .708.708L8.707 8l2.647 2.646a.5.5 0 0 1-.708.708L8 8.707l-2.646 2.647a.5.5 0 0 1-.708-.708L7.293 8 4.646 5.354a.5.5 0 0 1 0-.708z" />
            </svg>
          </button>
        </div>

        <div className="sidebar-content">
          <div className="mb-3">
            <select
              className="form-select sidebar-select"
              value={selectedEntreprise}
              onChange={(e) => setSelectedEntreprise(e.target.value)}
            >
              <option value="">Sélectionner une entreprise</option>
              {entreprises.map((ent) => (
                <option key={ent.id} value={ent.id}>
                  {ent.nom}
                </option>
              ))}
            </select>
          </div>

          <button
            className="btn btn-cta w-100 mb-4"
            onClick={() => setShowAddEntrepriseModal(true)}
          >
            <svg
              width="16"
              height="16"
              fill="currentColor"
              className="me-2"
              viewBox="0 0 16 16"
            >
              <path d="M8 4a.5.5 0 0 1 .5.5v3h3a.5.5 0 0 1 0 1h-3v3a.5.5 0 0 1-1 0v-3h-3a.5.5 0 0 1 0-1h3v-3A.5.5 0 0 1 8 4z" />
            </svg>
            Ajouter une entreprise
          </button>

          <nav className="sidebar-nav">
            <a
              href="#"
              className={`nav-link ${
                activeSection === "accueil" ? "active" : ""
              }`}
              onClick={() => {
                setActiveSection("accueil");
                setSidebarOpen(false);
              }}
            >
              <svg
                width="16"
                height="16"
                fill="currentColor"
                className="me-2"
                viewBox="0 0 16 16"
              >
