  const renderVeille = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Veille & Documents</h2>
        <p className="text-muted">Consultation et gestion des publications</p>
      </div>

      {/* Filtres */}
      <div className="card mb-4">
        <div className="card-header">
          <h5 className="mb-0">Filtres</h5>
        </div>
        <div className="card-body">
          <div className="row">
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Domaine</label>
              <select
                className="form-select"
                value={filters.domaine}
                onChange={(e) =>
                  setFilters({ ...filters, domaine: e.target.value })
                }
              >
                <option value="">Tous les domaines</option>
                {domainesActivite.map((domaine, index) => (
                  <option key={index} value={domaine}>
                    {domaine}
                  </option>
                ))}
              </select>
            </div>
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Date début</label>
              <input
                type="date"
                className="form-control"
                value={filters.dateDebut}
                onChange={(e) =>
                  setFilters({ ...filters, dateDebut: e.target.value })
                }
              />
            </div>
            <div className="col-lg-4 col-md-6 mb-3">
              <label className="form-label">Date fin</label>
              <input
                type="date"
                className="form-control"
                value={filters.dateFin}
                onChange={(e) =>
                  setFilters({ ...filters, dateFin: e.target.value })
                }
              />
            </div>
          </div>
        </div>
      </div>

      <div className="card mb-4">
        <div className="card-header">
          <h5 className="mb-0">Publications récentes</h5>
        </div>
        <div className="card-body">
          {loadingPublications ? (
            <p>Chargement des publications...</p>
          ) : errorPublications ? (
            <p className="text-danger">
              Erreur: {errorPublications.message}. Impossible de charger les
              publications.
            </p>
          ) : (
            <div className="table-responsive">
              <table className="table table-hover">
                {" "}
                {/* Correction de <taleble> en <table> */}
                <thead>
                  <tr>
                    <th>Date</th>
                    <th>Titre</th>
                    <th>Échéance</th>
                    <th>Domaine</th> {/* L'en-tête est déjà visible */}
                    <th>Actions</th>
                  </tr>
                </thead>
                <tbody>
                  {filteredPublications.map((pub) => (
                    <tr key={pub.id} style={{ cursor: "pointer" }}>
                      <td>
                        {/* Laissez ceci tel quel si vous voulez gérer la date de manière différente sur mobile */}
                        <div className="d-none d-md-block">{pub.date}</div>
                        <div className="d-md-none small">{pub.date}</div>
                      </td>
                      <td>
                        <div className="fw-bold">{pub.titre}</div>
                        {/* C'EST LA LIGNE À SUPPRIMER OU COMMENTER */}
                        {/* Cette ligne affichait "Échéance | Domaine" sous le titre sur mobile. */}
                        {/* <div className="d-md-none small text-muted">
              Échéance: {pub.echeance} | {pub.domaine}
            </div> */}
                      </td>
                      {/* C'EST LA LIGNE À MODIFIER POUR L'ÉCHÉANCE */}
                      {/* ANCIEN : <td className="d-none d-md-table-cell">{pub.echeance}</td> */}
                      <td>{pub.echeance}</td> {/* NOUVEAU : Toujours visible */}
                      {/* C'EST LA LIGNE À MODIFIER POUR LE DOMAINE */}
                      {/* ANCIEN : <td className="d-none d-md-table-cell"> */}
                      <td>
                        {" "}
                        {/* NOUVEAU : Toujours visible comme cellule de tableau */}
                        <span className="badge bg-primary">{pub.domaine}</span>
                      </td>
                      <td>
                        <button
                          type="button"
                          className="btn btn-sm btn-outline-primary"
                          onClick={() => {
                            setSelectedDocument(pub);
                            setShowModal(true);
                          }}
                        >
                          Voir
                        </button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          )}
        </div>
      </div>

      <div className="card">
        <div className="card-header">
          <h5 className="mb-0">Bibliothèque de documents</h5>
        </div>
        <div className="card-body">
          <div className="mb-3">
            <input
              type="text"
              className="form-control"
              placeholder="Rechercher par mot-clé..."
            />
          </div>
          <div className="row">
            {[1, 2, 3, 4].map((i) => (
              <div key={i} className="col-lg-3 col-md-4 col-sm-6 mb-3">
                <div className="card document-card">
                  <div className="card-body text-center">
                    <svg
                      width="48"
                      height="48"
                      fill="currentColor"
                      className="text-danger mb-2"
                      viewBox="0 0 16 16"
                    >
                      <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                    </svg>
                    <h6 className="card-title">Document {i}</h6>
                    <small className="text-muted">PDF - 2.3 MB</small>
                  </div>
                </div>
              </div>
            ))}
          </div>
        </div>
      </div>
    </div>
  );

  const renderAlertes = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Alertes & Résultats</h2>
        <p className="text-muted">
          Suivi des notifications et résultats de candidatures
        </p>
      </div>

      <div className="row">
        <div className="col-lg-8 mb-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Alertes non traitées</h5>
            </div>
            <div className="card-body">
              {alertes.map((alerte) => (
                <div
                  key={alerte.id}
