          </div>
        </div>

        <div className="col-lg-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Résultats récents</h5>
            </div>
            <div className="card-body">
              <div className="mb-3">
                <div className="d-flex justify-content-between align-items-center mb-1">
                  <span className="fw-bold">Rénovation Mairie Ouaga</span>
                  <span className="badge bg-success">Retenu</span>
                </div>
                <small className="text-muted d-block">
                  Résultat publié le 14/06/2025
                </small>
                <a href="#" className="small">
                  Voir l'annonce officielle
                </a>
              </div>

              <div className="mb-3">
                <div className="d-flex justify-content-between align-items-center mb-1">
                  <span className="fw-bold">
                    Construction école primaire fada
                  </span>
                  <span className="badge bg-danger">Non retenu</span>
                </div>
                <small className="text-muted d-block">
                  Résultat publié le 12/06/2025
                </small>
                <a href="#" className="small">
                  Voir l'annonce officielle
                </a>
              </div>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderProfil = () => (
    <div className="main-content">
      <div className="content-header">
        <h2>Profil</h2>
        <p className="text-muted">Gestion des informations de l'entreprise</p>
      </div>

      <div className="row">
        <div className="col-lg-8 mb-4">
          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Informations de l'entreprise</h5>
            </div>
            <div className="card-body">
              <form>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Nom de l'entreprise</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.nom}
                      onChange={(e) =>
                        setProfileData({ ...profileData, nom: e.target.value })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">SIRET</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.siret}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          siret: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Nom du représentant</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.nomRepresentant}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          nomRepresentant: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Prénom du représentant</label>
                    <input
                      type="text"
                      className="form-control"
                      value={profileData.prenomRepresentant}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          prenomRepresentant: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <div className="mb-3">
                  <label className="form-label">Adresse</label>
                  <input
                    type="text"
                    className="form-control"
                    value={profileData.adresse}
                    onChange={(e) =>
                      setProfileData({
                        ...profileData,
                        adresse: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="row">
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Email</label>
                    <input
                      type="email"
                      className="form-control"
                      value={profileData.email}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          email: e.target.value,
                        })
                      }
                    />
                  </div>
                  <div className="col-md-6 mb-3">
                    <label className="form-label">Téléphone</label>
                    <input
                      type="tel"
                      className="form-control"
                      value={profileData.telephone}
                      onChange={(e) =>
                        setProfileData({
                          ...profileData,
                          telephone: e.target.value,
                        })
                      }
                    />
                  </div>
                </div>
                <button type="submit" className="btn btn-cta">
                  Enregistrer les modifications
                </button>
              </form>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Secteur d'activité</h5>
            </div>
            <div className="card-body">
              <div className="row">
                {secteursActivite.map((secteur, index) => (
                  <div key={index} className="col-md-6 mb-2">
                    <div className="form-check">
                      <input
                        className="form-check-input"
                        type="checkbox"
                        name="secteurActivite"
                        id={`secteur-${index}`}
                        value={secteur}
                        checked={profileData.secteurActivite === secteur}
                        onChange={(e) =>
                          setProfileData({
                            ...profileData,
                            secteurActivite: e.target.value,
                          })
                        }
                      />
                      <label
                        className="form-check-label"
                        htmlFor={`secteur-${index}`}
                      >
                        {secteur}
                      </label>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-3">
                <label className="form-label">Autre secteur</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre secteur d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour le secteur
              </button>
            </div>
          </div>

          <div className="card mb-4">
            <div className="card-header">
              <h5 className="mb-0">Domaines d'activité</h5>
            </div>
            <div className="card-body">
              <div className="row">
                {domainesActivite.map((domaine, index) => (
                  <div key={index} className="col-md-6 mb-2">
                    <div className="form-check">
                      <input
                        className="form-check-input"
                        type="checkbox"
                        id={`domaine-${index}`}
                      />
                      <label
                        className="form-check-label"
                        htmlFor={`domaine-${index}`}
                      >
                        {domaine}
                      </label>
                    </div>
                  </div>
                ))}
              </div>
              <div className="mt-3">
                <label className="form-label">Autre domaine</label>
                <input
                  type="text"
                  className="form-control"
                  placeholder="Précisez votre domaine d'activité..."
                />
              </div>
              <button className="btn btn-cta mt-3">
                Mettre à jour les domaines
              </button>
            </div>
          </div>
        </div>

        <div className="col-lg-4">
          <div className="card">
            <div className="card-header">
              <h5 className="mb-0">Changer le mot de passe</h5>
            </div>
            <div className="card-body">
              <form>
                <div className="mb-3">
                  <label className="form-label">Mot de passe actuel</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">Nouveau mot de passe</label>
                  <input type="password" className="form-control" />
                </div>
                <div className="mb-3">
                  <label className="form-label">
                    Confirmer le nouveau mot de passe
                  </label>
                  <input type="password" className="form-control" />
                </div>
                <button type="submit" className="btn btn-cta w-100">
                  Mettre à jour le mot de passe
                </button>
              </form>
            </div>
          </div>
        </div>
      </div>
    </div>
  );

  const renderAddEntrepriseModal = () => (
    <div
      className={`modal fade ${showAddEntrepriseModal ? "show" : ""}`}
      style={{ display: showAddEntrepriseModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Ajouter une entreprise</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowAddEntrepriseModal(false)}
            ></button>
          </div>
          <form onSubmit={handleSubmitAddEntreprise}>
            <div className="modal-body">
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom de l'entreprise *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nom}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nom: e.target.value,
                      })
                    }
                    required
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">SIRET *</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.siret}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        siret: e.target.value,
                      })
                    }
                    required
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Téléphone</label>
                  <input
                    type="tel"
                    className="form-control"
                    value={addEntrepriseData.telephone}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        telephone: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Email</label>
                  <input
                    type="email"
                    className="form-control"
                    value={addEntrepriseData.email}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        email: e.target.value,
                      })
                    }
                  />
                </div>
              </div>
              <div className="row">
                <div className="col-md-6 mb-3">
                  <label className="form-label">Nom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.nomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        nomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
                <div className="col-md-6 mb-3">
                  <label className="form-label">Prénom du représentant</label>
                  <input
                    type="text"
                    className="form-control"
                    value={addEntrepriseData.prenomRepresentant}
                    onChange={(e) =>
                      setAddEntrepriseData({
                        ...addEntrepriseData,
                        prenomRepresentant: e.target.value,
                      })
                    }
                  />
                </div>
              </div>

              <div className="mb-3">
                <label className="form-label">Secteur d'activité</label>
                <select
                  className="form-select"
                  value={addEntrepriseData.secteurActivite}
                  onChange={(e) =>
                    setAddEntrepriseData({
                      ...addEntrepriseData,
                      secteurActivite: e.target.value,
                    })
                  }
                >
                  <option value="">Sélectionner un secteur</option>
                  {secteursActivite.map((secteur, index) => (
                    <option key={index} value={secteur}>
                      {secteur}
                    </option>
                  ))}
                </select>
              </div>

              <div className="mb-3">
                <label className="form-label">Domaines d'activité</label>
                <div className="row">
                  {domainesActivite.map((domaine, index) => (
                    <div key={index} className="col-md-6 mb-2">
                      <div className="form-check">
                        <input
                          className="form-check-input"
                          type="checkbox"
                          id={`add-domaine-${index}`}
                          checked={addEntrepriseData.domainesActivite.includes(
                            domaine
                          )}
                          onChange={() => handleAddEntrepriseDomaine(domaine)}
                        />
                        <label
                          className="form-check-label"
                          htmlFor={`add-domaine-${index}`}
                        >
                          {domaine}
                        </label>
                      </div>
                    </div>
                  ))}
                </div>
              </div>
            </div>
            <div className="modal-footer">
              <button
                type="button"
                className="btn btn-secondary"
                onClick={() => setShowAddEntrepriseModal(false)}
              >
                Annuler
              </button>
              <button type="submit" className="btn btn-cta">
                Ajouter l'entreprise
              </button>
            </div>
          </form>
        </div>
      </div>
    </div>
  );

  const renderModal = () => (
    <div
      className={`modal fade ${showModal ? "show" : ""}`}
      style={{ display: showModal ? "block" : "none" }}
      tabIndex="-1"
    >
      <div className="modal-dialog modal-lg">
        <div className="modal-content">
          <div className="modal-header">
            <h5 className="modal-title">Aperçu du document</h5>
            <button
              type="button"
              className="btn-close"
              onClick={() => setShowModal(false)}
            ></button>
          </div>
          <div className="modal-body">
            {selectedDocument && (
              <div>
                <h6>{selectedDocument.titre}</h6>
                <p className="text-muted">
                  Date de publication : {selectedDocument.date}
                </p>
                <p className="text-muted">
                  Échéance : {selectedDocument.echeance}
                </p>
                <div
                  className="bg-light p-4 text-center"
                  style={{ height: "400px" }}
                >
                  <svg
                    width="64"
                    height="64"
                    fill="currentColor"
                    className="text-muted mb-3"
                    viewBox="0 0 16 16"
                  >
                    <path d="M14 4.5V14a2 2 0 0 1-2 2H4a2 2 0 0 1-2-2V2a2 2 0 0 1 2-2h5.5L14 4.5zM9.5 3A1.5 1.5 0 0 0 11 4.5h2V14a1 1 0 0 1-1 1H4a1 1 0 0 1-1-1V2a1 1 0 0 1 1-1h5.5v2z" />
                  </svg>
                  <p>Aperçu du document PDF</p>
                </div>
              </div>
            )}
          </div>
          <div className="modal-footer">
            <button
              type="button"
              className="btn btn-secondary"
              onClick={() => setShowModal(false)}
            >
              Fermer
            </button>
            <button type="button" className="btn btn-cta">
              Télécharger
            </button>
          </div>
        </div>
      </div>
    </div>
  );

  const renderContent = () => {
    switch (activeSection) {
      case "accueil":
        return renderAccueil();
      case "veille":
        return renderVeille();
      case "alertes":
        return renderAlertes();
      case "profil":
        return renderProfil();
      default:
        return renderAccueil();
    }
  };

  return (
    <>
      <style jsx>{``}</style>

      <div className="dashboard-container">
        {renderMobileHeader()}
        {renderSidebar()}
        <div className="main-wrapper">{renderContent()}</div>
        {showModal && renderModal()}
        {showAddEntrepriseModal && renderAddEntrepriseModal()}
      </div>
    </>
  );
};

export default Dashboard;
